// Stessa guardia del flusso dei video: se il collegamento non è FreeLLMArena non scrive niente.
const GIUSTO = 'UCaDO6FcvstiPM83lh5eH7_w';
const canale = ($input.first().json.items || [])[0] || {};
if (canale.id !== GIUSTO) throw new Error('Canale sbagliato: il collegamento YouTube è su ' + (canale.snippet?.title || canale.id || 'nessun canale') + ', non su FreeLLMArena.');
return [{ json: { canale: GIUSTO } }];

// Salta i video già sistemati: così ogni giro costa poco della quota YouTube.
const memoria = $getWorkflowStaticData('global');
const fatti = memoria.fatti || [];
const ids = ($input.first().json.items || []).map((i) => i.contentDetails?.videoId).filter((v) => v && !fatti.includes(v)).slice(0, 20);
return ids.length ? [{ json: { ids: ids.join(',') } }] : [];

// Testo del primo commento (video/da-pubblicare/COMMENTO.md): solo frasi della descrizione del video, senza inventare.
function testoCommento(titolo, descrizione) {
  const righe = String(descrizione || '').split('\n').map((r) => r.trim()).filter(Boolean);
  const prima = righe.find((r) => !/^(Full |Sources?:|Project:|Chapters|\d+:\d)/i.test(r)) || String(titolo).replace(/#\w+/g, '').trim();
  const frasi = prima.match(/.+?[.!?](?=\s|$)/g) || [prima];
  let sunto = '';
  for (const f of frasi) if ((sunto + f).length <= 220) sunto += f; else break;
  if (!sunto) sunto = prima.slice(0, 217).replace(/[\s,;:]+\S*$/, '') + '...';
  if (!/[.!?]$/.test(sunto.trim())) sunto = sunto.trim() + '.';
  const link = [...String(descrizione || '').matchAll(/^Full (video|story|guide|rankings):\s*(\S+)/gim)].map((m) => 'Full ' + m[1].toLowerCase() + ': ' + m[2]);
  if (!link.some((l) => l.includes('freellmarena.com'))) link.push('Full rankings: https://freellmarena.com');
  const tema = titolo + ' ' + prima;
  const domanda = /\b(GPU|RTX|Radeon|RX \d|Arc \w?\d)/i.test(tema) ? 'Which GPU should we test next?'
    : /\bweek/i.test(tema) ? 'Which free model surprised you this week?'
    : /\b(model|weights|LLM)\b/i.test(tema) ? 'Which open model should we test next?'
    : 'Which AI story should we cover next?';
  return 'Quick summary: ' + sunto.trim() + ' ' + link.join(' ') + '\n' + domanda;
}

// 26/10/2026, Marco: poche scritture per volta, tanti commenti uguali possono sembrare spam. Tetto: 2 a giro, un giro ogni 2 ore.
const CANALE = 'UCaDO6FcvstiPM83lh5eH7_w';
const TETTO = 2;
const memoria = $getWorkflowStaticData('global');
memoria.fatti = memoria.fatti || [];
const video = $('Uno per video').all();
const scelti = [];
$input.all().forEach((it, i) => {
  const v = video[i].json;
  const gia = (it.json.items || []).some((t) => t.snippet?.topLevelComment?.snippet?.authorChannelId?.value === CANALE);
  if (gia || !Array.isArray(it.json.items)) memoria.fatti.push(v.video); // già commentato, o commenti chiusi
  else if (scelti.length < TETTO) scelti.push({ json: { video: v.video, canale: CANALE, testo: testoCommento(v.titolo, v.descrizione) } });
});
memoria.fatti = memoria.fatti.slice(-500);
return scelti;

// Segna i video commentati: il giro dopo non li rilegge.
const memoria = $getWorkflowStaticData('global');
memoria.fatti = [...(memoria.fatti || []), ...$('Prepara il testo').all().map((i) => i.json.video)].slice(-500);
return $input.all().map((it, i) => ({ json: { video: $('Prepara il testo').all()[i].json.video, commento: it.json.id } }));
